import{_ as o,a,b as e}from"./chunks/steamdeck-3.BwF2MKE5.js";import{_ as s,o as r,c as n,a5 as i}from"./chunks/framework.BjM_ivYE.js";const b=JSON.parse('{"title":"스팀덱 초기화·재설치","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/steamdeck-setup.md","filePath":"ko/manual/troubleshooting/steamdeck-setup.md","lastUpdated":1789720001000}'),l={name:"ko/manual/troubleshooting/steamdeck-setup.md"};function d(c,t,g,p,m,h){return r(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="스팀덱-초기화·재설치" tabindex="-1">스팀덱 초기화·재설치 <a class="header-anchor" href="#스팀덱-초기화·재설치" aria-label="Permalink to &quot;스팀덱 초기화·재설치&quot;">​</a></h1><p>스팀덱(Steam Deck)은 세팅이 완료된 상태로 출고되므로 평소에는 이 절차가 필요 없습니다. 공장 초기화를 했거나, 가지고 있던 스팀덱에 RBQ 앱을 설치해 쓰고 싶을 때 아래 순서대로 세팅하세요. 정상적으로 부팅되지 않거나 설정이 꼬였을 때도 이 절차로 되돌릴 수 있습니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>공장 초기화를 하면 <strong>사용자 데이터와 구성이 모두 지워지고 SteamOS가 다시 설치</strong>됩니다. 저장해 둔 설정과 파일을 먼저 백업하세요.</p></div></div><h2 id="factory-reset" tabindex="-1">1. 공장 초기화 <a class="header-anchor" href="#factory-reset" aria-label="Permalink to &quot;1. 공장 초기화 {#factory-reset}&quot;">​</a></h2><p>기기가 정상적으로 부팅된다면 운영체제 설정에서 공장 출고 상태로 되돌릴 수 있습니다.</p><ol><li><strong>스팀(Steam)</strong> 버튼을 누릅니다.</li><li><strong>설정</strong> 메뉴를 선택합니다.</li><li><strong>시스템</strong> 탭으로 이동합니다.</li><li>맨 아래로 스크롤해 <strong>고급</strong> 항목의 <strong>공장 출고 시 상태로 초기화</strong>를 선택합니다.</li><li><strong>공장 초기화</strong> 버튼을 눌러 확정합니다.</li></ol><p>초기화가 끝나면 Steam 계정을 생성하고 로그인합니다.</p><h2 id="desktop-mode" tabindex="-1">2. 데스크톱 모드로 전환 <a class="header-anchor" href="#desktop-mode" aria-label="Permalink to &quot;2. 데스크톱 모드로 전환 {#desktop-mode}&quot;">​</a></h2><ol><li><strong>스팀(Steam)</strong> 버튼을 누릅니다.</li><li><strong>전원</strong> 메뉴를 선택합니다.</li><li><strong>데스크톱 모드로 전환</strong>을 누릅니다.</li></ol><h2 id="download" tabindex="-1">3. 앱 내려받기 <a class="header-anchor" href="#download" aria-label="Permalink to &quot;3. 앱 내려받기 {#download}&quot;">​</a></h2><p>데스크톱 모드에서 브라우저로 <a href="/RBQ/ko/manual/downloads/">다운로드</a> 페이지에 접속해 <strong>RBQ Controller (Linux · Steam Deck)</strong> 를 내려받습니다. 받는 파일은 <code>rbq-controller-x86_64.AppImage</code> 입니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>처음 받는 파일은 <strong>어느 폴더에 두어도 됩니다.</strong> 아래 순서대로 한 번 실행한 뒤 앱 안에서 <strong>온라인 설치</strong>를 누르면, 앱이 <code>/home/deck/Documents/RBQ/</code> 아래에 설치 폴더를 스스로 만들고 <code>latest</code> 링크를 걸어 줍니다. 이후 업데이트는 그 링크만 옮기므로 <strong>Steam 에 등록한 바로가기를 다시 만들 필요가 없습니다.</strong></p></div></div><h2 id="permission" tabindex="-1">4. 실행 권한 부여 <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;4. 실행 권한 부여 {#permission}&quot;">​</a></h2><p>다운로드가 끝나면 <code>rbq-controller-x86_64.AppImage</code> 파일을 <strong>우클릭 → 속성 → 권한</strong>으로 이동해 <strong>파일을 프로그램으로 실행 허용</strong>에 체크합니다.</p><figure><img src="'+o+'" alt="AppImage 파일 우클릭 메뉴에서 속성 선택"><figcaption style="text-align:center;">우클릭 → 속성</figcaption></figure><figure><img src="'+a+'" alt="속성 권한 탭에서 파일을 프로그램으로 실행 허용 체크"><figcaption style="text-align:center;">권한 → 파일을 프로그램으로 실행 허용</figcaption></figure><h2 id="add-to-steam" tabindex="-1">5. Steam에 등록 <a class="header-anchor" href="#add-to-steam" aria-label="Permalink to &quot;5. Steam에 등록 {#add-to-steam}&quot;">​</a></h2><p>같은 파일을 다시 <strong>우클릭 → Add to Steam</strong> 을 선택합니다.</p><figure><img src="'+e+'" alt="AppImage 파일 우클릭 메뉴에서 Add to Steam 선택"><figcaption style="text-align:center;">우클릭 → Add to Steam</figcaption></figure><h2 id="launch" tabindex="-1">6. SteamOS로 부팅해 실행 <a class="header-anchor" href="#launch" aria-label="Permalink to &quot;6. SteamOS로 부팅해 실행 {#launch}&quot;">​</a></h2><ol><li>왼쪽 아래 <strong>스팀 아이콘</strong> → <strong>컴퓨터 끄기</strong> 로 전원을 종료한 뒤 SteamOS로 부팅합니다.</li><li>왼쪽 아래 <strong>STEAM</strong> 버튼을 누르고 <strong>라이브러리 → STEAM 외부</strong>로 들어갑니다.</li><li>목록에서 <strong>rbq-controller</strong> 를 실행합니다.</li></ol><p>앱이 뜨면 <strong>로봇 설정 → 소프트웨어 업데이트</strong>에서 <strong>온라인 설치</strong>를 눌러 설치 폴더를 만들어 두세요 — 이후 앱 업데이트가 이 자리에서 바로 됩니다.</p><p>이후 로봇 연결 절차는 <a href="/RBQ/ko/manual/operation/controller-wifi-connect.html">컨트롤러와 Wi-Fi 연결</a>을 참고하세요.</p>',23)])])}const _=s(l,[["render",d]]);export{b as __pageData,_ as default};
